-- Reuse synthetic owner/exercises from assisted-bodyweight.sql.
set role authenticated;
set request.jwt.claim.sub='88888888-0000-4000-8000-000000000001';
select public.add_missed_set('77777777-0000-4000-8000-000000000001','88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,8,null,0);
select pg_temp.expect((select set_no=3 and logged_at=(select ended_at from public.workouts where id=workout_id) from public.sets where id='77777777-0000-4000-8000-000000000001'),'missed assisted set uses historical training date');
select pg_temp.expect((select sets_changed_at is not null from public.workouts where id='88888888-0000-4000-8000-000000000004'),'finished edits invalidate saved analysis');
select public.add_missed_set('77777777-0000-4000-8000-000000000001','88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,8,null,0);
select pg_temp.expect((select count(*) from public.sets where workout_id='88888888-0000-4000-8000-000000000004' and deleted_at is null and set_type='working')=3,'retry is idempotent');
select pg_temp.expect_error($$select public.add_missed_set('77777777-0000-4000-8000-000000000001','88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,9,null,0)$$,'reused ID cannot change saved data');
select pg_temp.expect((select working_sets=3 and bodyweight_sets=2 from public.assisted_session_progress where exercise_id='88888888-0000-4000-8000-000000000003' and workout_id='88888888-0000-4000-8000-000000000004'),'missed set updates assisted progress');
select pg_temp.expect((select bool_and(volume_kg is null) and sum(excluded_sets)=5 from public.weekly_exercise_volume where exercise_id='88888888-0000-4000-8000-000000000003'),'missed assisted set stays excluded from lifted volume');
update public.sets set deleted_at=now() where id='77777777-0000-4000-8000-000000000001';
select public.add_missed_set('77777777-0000-4000-8000-000000000002','88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,7,null,5);
select pg_temp.expect((select set_no=3 from public.sets where id='77777777-0000-4000-8000-000000000002'),'fills a deleted gap without changing original rows');
select public.add_missed_set('77777777-0000-4000-8000-000000000003','88888888-0000-4000-8000-00000000000c','88888888-0000-4000-8000-00000000000b','working',45,3.75,10);
select pg_temp.expect((select weight_kg=45 and added_kg=3.75 and assistance_kg is null from public.sets where id='77777777-0000-4000-8000-000000000003'),'historical standard set does not inherit current assisted exercise mode');
select pg_temp.expect((select sum(volume_kg)=912.5 from public.weekly_exercise_volume where exercise_id='88888888-0000-4000-8000-00000000000b'),'SQL volume includes new standard set');
select public.add_missed_set('77777777-0000-4000-8000-000000000004','88888888-0000-4000-8000-00000000000c','88888888-0000-4000-8000-00000000000b','warmup',100,0,20);
select pg_temp.expect((select sum(volume_kg)=912.5 from public.weekly_exercise_volume where exercise_id='88888888-0000-4000-8000-00000000000b'),'missed warmup never changes working volume');
select pg_temp.expect(public.claim_workout_review_refresh('88888888-0000-4000-8000-000000000004',(select sets_changed_at from public.workouts where id='88888888-0000-4000-8000-000000000004')),'first refresh claims the edit');
select pg_temp.expect(not public.claim_workout_review_refresh('88888888-0000-4000-8000-000000000004',(select sets_changed_at from public.workouts where id='88888888-0000-4000-8000-000000000004')),'second refresh shares in-flight work');
select pg_temp.expect(not public.claim_workout_review_refresh('88888888-0000-4000-8000-000000000004',now()-interval '1 day'),'outdated edit revision cannot claim refresh');
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-00000000000b','working',30,0,10)$$,'cannot add an exercise absent from workout');
insert into public.workouts(id) values('77777777-0000-4000-8000-000000000005');
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'77777777-0000-4000-8000-000000000005','88888888-0000-4000-8000-000000000003','working',null,0,10,null,5)$$,'unfinished workout cannot use historical add');
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,null,null,5)$$,'missing reps rejected');
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,10,null,-5)$$,'negative help rejected');
insert into public.exercises(id,name,equipment,per_hand) values('77777777-0000-4000-8000-000000000006','Missed dumbbell press','dumbbell',true),('77777777-0000-4000-8000-000000000007','Missed plank','bodyweight',false);
insert into public.sets(id,workout_id,exercise_id,set_no,weight_kg,reps) values(gen_random_uuid(),'88888888-0000-4000-8000-00000000000c','77777777-0000-4000-8000-000000000006',1,10,10);
insert into public.sets(id,workout_id,exercise_id,set_no,duration_sec) values(gen_random_uuid(),'88888888-0000-4000-8000-00000000000c','77777777-0000-4000-8000-000000000007',1,30);
select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-00000000000c','77777777-0000-4000-8000-000000000006','working',12,0,10);
select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-00000000000c','77777777-0000-4000-8000-000000000007','working',null,0,null,45);
select pg_temp.expect((select sum(volume_kg)=220 from public.weekly_exercise_volume where exercise_id='77777777-0000-4000-8000-000000000006'),'missed per-hand set preserves existing SQL volume convention');
select pg_temp.expect((select sum(excluded_sets)=2 from public.weekly_exercise_volume where exercise_id='77777777-0000-4000-8000-000000000007'),'missed hold excluded from loaded volume');
update public.workouts set ended_at=now(),cancelled_at=now() where id='77777777-0000-4000-8000-000000000005';
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'77777777-0000-4000-8000-000000000005','88888888-0000-4000-8000-000000000003','working',null,0,10,null,5)$$,'cancelled workout cannot use historical add');
insert into public.workouts(id,started_at,ended_at,source) values('77777777-0000-4000-8000-000000000008',now()-interval '1 hour',now(),'baseline');
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'77777777-0000-4000-8000-000000000008','88888888-0000-4000-8000-000000000003','working',null,0,10,null,5)$$,'baseline record cannot use historical add');
set request.jwt.claim.sub='88888888-0000-4000-8000-000000000002';
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),'88888888-0000-4000-8000-000000000004','88888888-0000-4000-8000-000000000003','working',null,0,10,null,0)$$,'another owner cannot append');
select pg_temp.expect(not public.claim_workout_review_refresh('88888888-0000-4000-8000-000000000004',now()),'another owner cannot request refresh');
set role anon;
select pg_temp.expect_error($$select public.add_missed_set(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'working',10,0,10)$$,'anonymous append rejected');
select pg_temp.expect_error($$select public.claim_workout_review_refresh(gen_random_uuid(),now())$$,'anonymous refresh rejected');
reset role;
